#include <iostream>

class Circle {
private:
    double radius;
    // C++17 inline static variable: enables in-class initialization
    inline static int numberOfObjects = 0;

public:
    Circle() : radius(1.0) {
        ++numberOfObjects;
    }

    explicit Circle(double newRadius) : radius(newRadius >= 0 ? newRadius : 0) {
        ++numberOfObjects;
    }

    double getRadius() const {
        return radius;
    }

    void setRadius(double newRadius) {
        radius = (newRadius >= 0) ? newRadius : 0;
    }

    double getArea() const {
        return radius * radius * 3.14159;
    }

    static int getNumberOfObjects() {
        return numberOfObjects;
    }
};

int main() {
    std::cout << "Number of circle objects created: "
              << Circle::getNumberOfObjects() << "\n";

    Circle circle1;
    std::cout << "The area of the circle of radius "
              << circle1.getRadius() << " is " << circle1.getArea() << "\n";
    std::cout << "Number of circle objects created: "
              << Circle::getNumberOfObjects() << "\n";

    Circle circle2(5.0);
    std::cout << "The area of the circle of radius "
              << circle2.getRadius() << " is " << circle2.getArea() << "\n";
    std::cout << "Number of circle objects created: "
              << Circle::getNumberOfObjects() << "\n";

    circle1.setRadius(3.3);
    std::cout << "The area of the circle of radius "
              << circle1.getRadius() << " is " << circle1.getArea() << "\n";

    // Both calls return the exact same shared class count
    std::cout << "circle1.getNumberOfObjects() returns "
              << circle1.getNumberOfObjects() << "\n";
    std::cout << "circle2.getNumberOfObjects() returns "
              << circle2.getNumberOfObjects() << "\n";

    return 0;
}

#include <iostream>

class Circle {
private:
    double radius;
    inline static int numberOfObjects = 0;

public:
    Circle() : radius(1.0) {
        ++numberOfObjects;
    }

    explicit Circle(double newRadius) : radius(newRadius >= 0 ? newRadius : 0) {
        ++numberOfObjects;
    }

    // Constant member functions: guaranteed not to modify the object
    double getRadius() const {
        return radius;
    }

    double getArea() const {
        return radius * radius * 3.14159;
    }

    // Mutator function: modifies state, cannot be const
    void setRadius(double newRadius) {
        radius = (newRadius >= 0) ? newRadius : 0;
    }

    static int getNumberOfObjects() {
        return numberOfObjects;
    }
};

// Parameter c is passed by const reference for defensive programming and efficiency
void printCircle(const Circle& c) {
    // c.getRadius() and c.getArea() compile because they are const member functions
    std::cout << "The area of the circle of radius "
              << c.getRadius() << " is " << c.getArea() << "\n";
}

int main() {
    Circle c1(2.5);
    printCircle(c1);

    const Circle c2(4.0);
    printCircle(c2);

    std::cout << "Total circles: " << Circle::getNumberOfObjects() << "\n";
    return 0;
}

